-- Restricted categories: can be catalogued, never dealable
INSERT INTO public.catalog_categories (slug, name, level, schema_id, ondc_code, is_restricted, sort_order) VALUES
  ('restricted', 'Restricted (not dealable)', 1, 'general', NULL, true, 9990)
ON CONFLICT (slug) DO UPDATE SET is_restricted = true;
INSERT INTO public.catalog_categories (parent_id, slug, name, level, schema_id, ondc_code, is_restricted, sort_order)
SELECT p.id, v.slug, v.name, 2, v.schema_id, v.ondc, true, v.ord FROM (VALUES
  ('pharmacy-healthcare', 'pharmacy-prescription', 'Prescription Medicines', 'health', 'ONDC:RET19', 1),
  ('restricted', 'restricted-tobacco', 'Tobacco Products', 'general', NULL, 1),
  ('restricted', 'restricted-alcohol', 'Alcoholic Beverages', 'grocery', NULL, 2)
) AS v(parent_slug, slug, name, schema_id, ondc, ord)
JOIN public.catalog_categories p ON p.slug = v.parent_slug
ON CONFLICT (slug) DO UPDATE SET is_restricted = true;

