-- Search aliases ("Rava/Sooji" is found by "sooji" and "rava")
INSERT INTO public.catalog_aliases (product_id, alias, language)
SELECT p.id, v.alias, 'en' FROM (VALUES
  ('DFT00005', 'Rava'),
  ('DFT00005', 'Sooji')
) AS v(code, alias)
JOIN public.catalog_products p ON p.code = v.code
ON CONFLICT DO NOTHING;

-- Provenance: every imported product came from the AI-generated Phase 1 workbook
INSERT INTO public.catalog_sources (product_id, source_name, confidence)
SELECT p.id, 'DealFynd Phase 1 workbook (AI-generated generic taxonomy, unverified)', 0.30
FROM public.catalog_products p
WHERE p.source = 'import' AND p.code LIKE 'DFT%'
  AND NOT EXISTS (SELECT 1 FROM public.catalog_sources s WHERE s.product_id = p.id);

COMMIT;

-- Check
SELECT (SELECT count(*) FROM public.catalog_categories) AS categories,
       (SELECT count(*) FROM public.catalog_merchant_categories) AS shop_types,
       (SELECT count(*) FROM public.catalog_products) AS products,
       (SELECT count(*) FROM public.catalog_product_merchant_categories) AS shop_links,
       (SELECT count(*) FROM public.catalog_aliases) AS aliases;
